head.script:
scwin.test = function() {
    $w.log("main" + "_initScript");
}
scwin.test2 = function() {
    $w.log("main" + "_initScript2");
}
scwin.post1 = function() {
    $w.log("main" + "_postScript1");
}
scwin.post2 = function() {
    $w.log("main" + "_postScript2");
}
scwin.onpageload = function() {
    $w.log("main" + "_onpageload");
    if (console.log) {
        console.log("main" + "_onpageload");
    }
}
scwin.trigger1_onclick = function() {
    w1.setSrc("wframe_setSrc_WPFF-129_(WSQ-3298)_sub.xml");
    var err = WebSquare.logger.getErrorLog();
    if (err) {
        //alert(err);
        alertLog = "error";
    } else {
        //alert("setSrc PASS");
        alertLog = "setSrc PASS";
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 'setSrc_test'버튼을 클릭한다.
    //1. After running the main sample, click the 'setSrc_test' button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 정상알림 'setSrc PASS'값이 보여진다.(이전에는 오류발생알림이 보여짐)
    //1. Normal notification 'setSrc PASS' value is displayed (previously error notification is shown)
    WebSquare.wUnit.addCommand("assert", "alertLog == 'setSrc PASS'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.alertLog = undefined;
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 19-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
